Translate the following GNU C++11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

int main() {
    int x, y, n;
    scanf("%d %d %d", &x, &y, &n);
    long long numerator = 0, denominator = 1;
    double min_diff = 1e18;
    for (int b = 1; b <= n; ++b) {
        long long a_lower_bound = b * x / y;
        long long a_upper_bound = (b * x + y - 1) / y;
        double diff_lower = fabs((double)a_lower_bound / b - (double)x / y);
        double diff_upper = fabs((double)a_upper_bound / b - (double)x / y);
        if (diff_lower < min_diff && fabs(diff_lower - min_diff) > 1e-15) {
            min_diff = diff_lower;
            numerator = a_lower_bound;
            denominator = b;
        }
        if (diff_upper < min_diff && fabs(diff_upper - min_diff) > 1e-15) {
            min_diff = diff_upper;
            numerator = a_upper_bound;
            denominator = b;
        }
    }
    printf("%lld/%lld", numerator, denominator);
}
